describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discount from multiple policies on original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so this is straightforward
      const p1 = new NoDiscountPolicy();
      const p2 = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // 10% of 5000 = 500, + 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal after previous discounts", () => {
      const p1 = new FixedAmountDiscountPolicy(500); // 500 off 10000 → remaining 9500
      const p2 = new PercentageDiscountPolicy(10); // 10% of 9500 = 950
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1450);
    });

    it("order matters: percentage first, fixed second gives different result", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000 → remaining 9000
      const p2 = new FixedAmountDiscountPolicy(500); // 500 off 9000
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(10000); // takes all
      const p2 = new FixedAmountDiscountPolicy(500); // nothing left
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps individual steps to remaining", () => {
      // FixedAmount(2000) on subtotal 1000 — the step is min(1000, 1000) = 1000
      const p1 = new FixedAmountDiscountPolicy(2000);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

