toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 regardless of lines or subtotal", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 10000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 10000)).toBe(0);
    });

    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(799);
    });

    it("returns 0 when subtotal >= freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns flat fee when subtotal is just below threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(799);
    });

    it("returns 0 when subtotal exceeds threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 10000)).toBe(0);
    });

    it("charges flat fee when no freeOver threshold set", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100000)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 5.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 10000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 10000),
      ).toBe(0);
    });

    it("selects first bracket when weight <= upToGrams", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 250, 1)], 10000),
      ).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 10000),
      ).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 10000),
      ).toBe(700);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 5000, 1)], 10000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 10000),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 10000, 1)], 10000),
      ).toBe(1200);
    });

    it("sorts unsorted brackets correctly", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(
        calc.computeShippingCents([makeLine("a", 250, 1)], 0),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
      // 300*2 + 500*1 = 1100 → bracket 2000 → 700
      expect(calc.computeShippingCents(lines, 10000)).toBe(700);
    });
  });
});

